using System;using Ossastra.CharacterCore;
class OffhandTests{static int n;static void Check(bool ok,string name){if(!ok)throw new Exception(name);n++;}static void Main(){var type=typeof(Health).Assembly.GetType("Ossastra.CharacterCore.OffhandActionState");Check(type!=null,"missing independent offhand clock");dynamic state=Activator.CreateInstance(type,"owner");var id=Guid.NewGuid();Check(state.TryAccept(id,"gear",3),"accept");Check(!state.TryAccept(Guid.NewGuid(),"gear",3),"busy/CD reject");Check(state.Advance(.04,true,false)==null,"before release");Check(state.Advance(1,true,true)==null,"pause freezes release");AttackRelease release=state.Advance(.02,true,false);Check(release!=null&&release.ActionId==id&&release.ActorId=="owner","frozen release identity");Check(state.Advance(.2,true,false)==null,"one release");double cd=state.CooldownRemaining;state.Advance(8,false,false);Check(Math.Abs(state.CooldownRemaining-cd)<.0001,"noncurrent CD frozen");state.Advance(5,true,false);Check(state.TryAccept(Guid.NewGuid(),"gear",3),"CD permits new");state.CancelPending();Check(state.Advance(1,true,false)==null,"cancel no release");Check(state.CooldownRemaining>0,"cancel no refund CD");Console.WriteLine(n+" offhand contracts passed");}}
